bool parseResolution(const std::string &value, uint32_t &width, uint32_t &height)
{
  const size_t separator = value.find_first_of("xX");
  if (separator == std::string::npos)
    return false;
  try
  {
    const unsigned long parsedWidth = std::stoul(value.substr(0u, separator));
    const unsigned long parsedHeight = std::stoul(value.substr(separator + 1u));
    if (parsedWidth == 0ul || parsedHeight == 0ul || parsedWidth > std::numeric_limits<uint32_t>::max() || parsedHeight > std::numeric_limits<uint32_t>::max())
      return false;
    width = static_cast<uint32_t>(parsedWidth);
    height = static_cast<uint32_t>(parsedHeight);
    return true;
  }
  catch (const std::exception &)
  {
    return false;
  }
}

bool parsePlanetTile(const std::string &value, procedural::PlanetTileAddress &tile)
{
  unsigned face = 0u;
  unsigned level = 0u;
  unsigned x = 0u;
  unsigned y = 0u;
  char trailing = '\0';
  if (std::sscanf(value.c_str(), "%u,%u,%u,%u%c", &face, &level, &x, &y, &trailing) != 4)
    return false;
  tile = {static_cast<uint8_t>(face), static_cast<uint8_t>(level), static_cast<uint32_t>(x), static_cast<uint32_t>(y)};
  return face <= 5u && level <= 31u && procedural::validPlanetTileAddress(tile);
}

