        os::Logger::logf(
            "Terrain shared VG event: install slot=%u addr=(%d,%d,lod%u) pages=%zu parent=%u",
            slot, installedPage != nullptr ? installedPage->address.x : 0,
            installedPage != nullptr ? installedPage->address.z : 0,
            installedPage != nullptr ? installedPage->address.spatialLOD : 0u,
            static_cast<size_t>(entry.pageCount), parent);
