    // two-phase off the prepass emits the same visible set the final pass
    // does, so its stats describe the actually drawn cut in both modes.
    float cutMaxTriangleEdgePx = 0.0f;
    uint32_t cutGiantClusters = 0u;
    uint32_t cutGiantStreamingLeaves = 0u;
    uint32_t cutGiantTrueLeaves = 0u;
    float cutMaxStreamingLeafErrorPx = 0.0f;
    float cutGiantTrueLeafParentPx = 0.0f;
    float cutGiantRefinableSelfPx = 0.0f;
    uint32_t cutTinyClusters = 0u;
    uint32_t cutDrawnClusters = 0u;
