  TerrainVGCounters readTerrainVGCounters()
  {
    TerrainVGCounters counters{};
    if (!terrainVGCountersReadback.isValid())
      return counters;
    constexpr uint32_t kWords = static_cast<uint32_t>(terrainVGCounterBytes / sizeof(uint32_t));
    std::array<uint32_t, kWords * 2u> words{};
    graph->bufferRead(
        terrainVGCountersReadback,
        0u,
        terrainVGCounterBytes * 2u,
        [&](const void *data)
        { std::memcpy(words.data(), data, terrainVGCounterBytes * 2u); });
    counters.valid = true;
    // Indices mirror virtualgeometrydata.wgsl; the first block is the final
    // (phase-two) culling pass, the second the phase-one pass. Under two-pass
    // occlusion either phase can emit a cluster, so the cut contract combines
    // both: maxima for pixel measures, sums for counts.
    const uint32_t pre = kWords;
    counters.clusterQueueSize = words[1];
    counters.hardwareVisibleClusters = words[2];
    counters.softwareVisibleClusters = words[4];
    counters.prepassQueueSize = words[pre + 1u];
    counters.prepassVisibleClusters = words[pre + 2u] + words[pre + 4u];
    const auto asFloat = [](uint32_t bits)
    {
      float value = 0.0f;
      std::memcpy(&value, &bits, sizeof(value));
      return value;
    };
    const auto maxFloat = [&](const uint32_t index)
    { return std::max(asFloat(words[index]), asFloat(words[pre + index])); };
    const auto sum = [&](const uint32_t index) { return words[index] + words[pre + index]; };
    counters.cutMaxTriangleEdgePx = maxFloat(8u);
    counters.cutGiantClusters = sum(9u);
    counters.cutGiantStreamingLeaves = sum(10u);
    counters.cutGiantTrueLeaves = sum(11u);
    counters.cutMaxStreamingLeafErrorPx = maxFloat(12u);
    counters.cutGiantTrueLeafParentPx = maxFloat(13u);
    counters.cutGiantRefinableSelfPx = maxFloat(14u);
    counters.cutTinyClusters = sum(15u);
    counters.cutDrawnClusters = sum(16u);
    return counters;
  }
