        brickMicroPrepareRecords = storage("svr.sample.brickMicroPrepareRecords", uint64_t{brickMicroPrepareRecordCapacity} * sizeof(svrRendering::SparseVoxelMicroBrickRecordGPU), false, true);
        brickMicroPrepareResiduals = storage("svr.sample.brickMicroPrepareResiduals", uint64_t{brickVisibleCapacity} * sizeof(svrRendering::SparseVoxelMicroResidualGPU), false, true);
