        updateTerrainPageStates(*inPlanetChunks, 0u);
        std::string runtimeTableError;
        const auto &runtimeTable = inPlanetChunks->terrainRuntimePageTable;
        const size_t runtimePageHeadroom = std::max<size_t>(
            runtimeTable.pages.size(),
            std::max<size_t>(terrainPageRequestCapacity, 1u) * 16u);
        const size_t runtimeNodeHeadroom = std::max<size_t>(
            runtimeTable.nodes.size(),
            size_t{brickNodeStorageCapacity} + runtimePageHeadroom);
