      brickPreviouslyVisible = storage("svr.sample.brickPreviouslyVisible", uint64_t{brickVisibleCapacity} * sizeof(uint32_t));
      brickPreviouslyVisibleSeed.assign(brickHierarchy.nodes.size(), 1u);
      writeVector(*graph, brickPreviouslyVisible, brickPreviouslyVisibleSeed);
      writeVector(*graph, brickNodes, brickHierarchy.nodes);
