      writeVector(*graph, brickRootIndices, brickHierarchy.rootIndices);
      writeVector(*graph, brickOccupancy, brickHierarchy.occupancy);
      writeVector(*graph, brickMaterials, brickMaterialIndexWords);
      writeVector(*graph, brickMicroSurfaceData, brickMicroSurfaceWords);
