      brickHierarchyCounts.occupancy = brickHierarchy.occupancy.size();
      brickHierarchyCounts.materialIndices = brickHierarchy.materialIndices.size();
      brickHierarchyCounts.microSurfaceData = brickHierarchy.microSurfaceData.size();
      brickHierarchyCounts.palette = brickHierarchy.palette.size();
      brickHierarchyCounts.materialWords = brickMaterialIndexWords.size();
      brickHierarchyCounts.microSurfaceWords = brickMicroSurfaceWords.size();
      brickHierarchyCounts.paletteDescriptorWords = brickPaletteDescriptorWords.size();
      brickHierarchyCounts.paletteMicroWords = brickPaletteMicroWords.size();
