      writeVector(*graph, brickVoxelGeometryPrograms, voxelMaterialManager.geometryPrograms());
      writeVector(*graph, brickVoxelGeometryInstructions, voxelMaterialManager.geometryInstructions());
      writeVector(*graph, brickVoxelGeometryParameters, voxelMaterialManager.geometryParameters());
      writeVector(*graph, brickVoxelMaterialFieldDefaults, voxelMaterialManager.materialFieldDefaults());
      writeVector(*graph, brickVoxelShadingPrograms, voxelMaterialManager.shadingPrograms());
