      state.temporal.frameGenerationDebugMode = static_cast<uint32_t>(frameGenerationDebug);
#if defined(__APPLE__)
    ImGui::EndDisabled();
#endif
    ImGui::EndDisabled();
    ImGui::EndDisabled();
    ImGui::SeparatorText("History validation");
    ImGui::Checkbox("Identity rejection", &state.svgf.identityRejection);
    ImGui::SameLine();
    ImGui::TextDisabled("Uses LOD-stable surface identity");
    ImGui::BeginDisabled(!state.svgf.identityRejection);
    ImGui::SliderFloat("Identity rejection strength", &state.svgf.identityRejectionStrength, 0.0f, 1.0f, "%.2f");
    ImGui::SetItemTooltip(
        "How much an identity mismatch rejects history on its own, with depth "
        "and normal agreeing. 1.0 is the old veto. Edge energy has a measured "
        "minimum at 0.15.");
    ImGui::SliderFloat("Normal rejection strength", &state.svgf.normalRejectionStrength, 0.0f, 1.0f, "%.2f");
    ImGui::SetItemTooltip(
        "How much a normal mismatch rejects history when identity confirms the "
        "surface is still under the pixel. 1.0 is the old veto, which fires on "
        "every silhouette pixel jitter moves across an axis-aligned face.");
