    ImGui::TextDisabled("Ray-space W clamp");
    ImGui::Checkbox("Hardware ReSTIR shadows", &state.sceneLighting.hardwareRayTrace);
    ImGui::SliderFloat("Ray-tracing scene error (pixels)", &state.sceneLighting.hardwareSceneErrorPixels, 0.25f, 32.0f, "%.2f", ImGuiSliderFlags_Logarithmic);
    ImGui::Checkbox("MetalFX ReSTIR denoiser (when supported)", &state.sceneLighting.metalFxDenoiser);
    ImGui::Checkbox("Spatial ReSTIR reuse", &state.sceneLighting.spatialReuseEnabled);
    ImGui::Checkbox("Screen-space traces", &state.sceneLighting.screenTraceEnabled);
    ImGui::SameLine();
    ImGui::TextDisabled(state.sceneLighting.screenTraceEnabled ? "Screen hits, then world fallback" : "World traces only");
    ImGui::BeginDisabled(!state.sceneLighting.screenTraceEnabled);
    // A screen hit wins over the world answer unconditionally, so these two
    // control how much of the frame can disagree with the world trace: the
    // span is where both traces answer, and the slab is how wrong a single
    // screen surface can be about its own depth.
    ImGui::SliderFloat("Screen trace span (cells)", &state.sceneLighting.screenTraceCellSpan, 1.0f, 32.0f, "%.0f");
    ImGui::SameLine();
    ImGui::TextDisabled("Overlap with the world trace");
    ImGui::SliderFloat("Screen slab (cells)", &state.sceneLighting.screenTraceMaximumThicknessCells, 1.0f, 16.0f, "%.0f");
    ImGui::SliderFloat("Screen slab steps", &state.sceneLighting.screenTraceThicknessSteps, 0.0f, 4.0f, "%.2f");
    ImGui::SameLine();
    ImGui::TextDisabled("Lower if surfaces cast false near shadows");
    ImGui::EndDisabled();
    const uint64_t pixelSlotCount = static_cast<uint64_t>(rayWidth) * static_cast<uint64_t>(rayHeight);
    const uint64_t selectedRayCount = pixelSlotCount * state.sceneLighting.raysPerPixel;
    const uint64_t candidateRayCount = pixelSlotCount * state.sceneLighting.restirCandidatesPerPixel;
    ImGui::Text("Ray dispatch: %u x %u x %u = %llu traced rays", rayWidth, rayHeight, state.sceneLighting.raysPerPixel, static_cast<unsigned long long>(selectedRayCount));
    ImGui::Text("Light candidates: %llu", static_cast<unsigned long long>(candidateRayCount));
    ImGui::TextDisabled("Lane 1 reserves sky visibility; ReSTIR partitions non-sky candidates across the rest.");
    ImGui::Checkbox("Directional light", &state.sceneLighting.directionalEnabled);
    ImGui::BeginDisabled(!state.sceneLighting.directionalEnabled);
    ImGui::DragFloat3("Directional direction", &state.sceneLighting.directionalDirection[0], 0.01f, -1.0f, 1.0f);
    ImGui::ColorEdit3("Directional color", &state.sceneLighting.directionalColor[0]);
    ImGui::DragFloat("Directional intensity", &state.sceneLighting.directionalIntensity, 0.1f, 0.0f, 1000.0f);
    ImGui::EndDisabled();
    ImGui::Checkbox("Sky light", &state.sceneLighting.skyEnabled);
    ImGui::BeginDisabled(!state.sceneLighting.skyEnabled);
    ImGui::DragFloat3("Sky up", &state.sceneLighting.skyUp[0], 0.01f, -1.0f, 1.0f);
    ImGui::ColorEdit3("Sky horizon", &state.sceneLighting.skyHorizonColor[0]);
    ImGui::ColorEdit3("Sky zenith", &state.sceneLighting.skyZenithColor[0]);
    ImGui::ColorEdit3("Sky ground", &state.sceneLighting.skyGroundColor[0]);
    ImGui::DragFloat("Sky intensity", &state.sceneLighting.skyIntensity, 0.05f, 0.0f, 100.0f);
    ImGui::DragFloat("Sky horizon curve", &state.sceneLighting.skyHorizonExponent, 0.01f, 0.01f, 8.0f);
    ImGui::EndDisabled();
    ImGui::SeparatorText("Material overrides");
    ImGui::Checkbox("Override roughness", &state.sceneLighting.materialRoughnessOverride);
    ImGui::BeginDisabled(!state.sceneLighting.materialRoughnessOverride);
    ImGui::SliderFloat("Roughness", &state.sceneLighting.materialRoughness, 0.0f, 1.0f, "%.2f");
    ImGui::EndDisabled();
    ImGui::Checkbox("Override metallic", &state.sceneLighting.materialMetallicOverride);
    ImGui::BeginDisabled(!state.sceneLighting.materialMetallicOverride);
    ImGui::SliderFloat("Metallic", &state.sceneLighting.materialMetallic, 0.0f, 1.0f, "%.2f");
    ImGui::EndDisabled();
    ImGui::TextDisabled("Unchecked keeps whatever the OBJ import produced");
    ImGui::SeparatorText("Voxel normal filtering");
    ImGui::SliderFloat("Normal smoothing", &state.sceneLighting.voxelNormalSmoothing, 0.0f, 1.0f, "%.2f");
    ImGui::SliderFloat("Normal depth sigma", &state.sceneLighting.voxelNormalDepthSigma, 0.25f, 4.0f, "%.2f px");
    ImGui::SliderFloat("Normal variance roughness", &state.sceneLighting.voxelNormalRoughnessBoost, 0.0f, 1.0f, "%.2f");
    ImGui::TextDisabled("Filters material normals; virtual face geometry is applied afterward");
    ImGui::SeparatorText("Voxel readability");
    ImGui::SliderFloat(
        "Per-voxel brightness", &state.sceneLighting.voxelBrightnessVariation,
        0.0f, 0.35f, "%.2f");
    ImGui::TextDisabled(
        "Stable per resolved terrain cell; applies to raster and Tree64");
    ImGui::SeparatorText("Distant voxel detail");
    ImGui::Checkbox("Smooth distant normals and albedo", &state.sceneLighting.distantVoxelSmoothing);
    ImGui::BeginDisabled(!state.sceneLighting.distantVoxelSmoothing);
    ImGui::SliderFloat("Smoothing start fraction", &state.sceneLighting.distantVoxelSmoothingStart, 0.0f, 1.0f, "%.2f");
    ImGui::SliderFloat("Smoothing end fraction", &state.sceneLighting.distantVoxelSmoothingEnd, 0.0f, 1.0f, "%.2f");
    const float smoothingReferenceDistance = state.sceneLighting.distantVoxelSmoothingReferenceDistance > 0.0f ? state.sceneLighting.distantVoxelSmoothingReferenceDistance : state.cameraFarPlane;
    ImGui::TextDisabled(
        "Start/end are fractions of a %.1f m %s reference; this is\n"
        "independent of the probe analytical cutoff.",
        static_cast<double>(smoothingReferenceDistance),
        state.sceneLighting.distantVoxelSmoothingReferenceDistance > 0.0f ? "terrain-local" : "camera-far-plane");
    ImGui::SliderFloat("Distant normal strength", &state.sceneLighting.distantVoxelNormalStrength, 0.0f, 1.0f, "%.2f");
    ImGui::SliderFloat("Distant albedo strength", &state.sceneLighting.distantVoxelAlbedoStrength, 0.0f, 1.0f, "%.2f");
    ImGui::SliderFloat("Distant filter radius", &state.sceneLighting.distantVoxelRadius, 1.0f, 4.0f, "%.0f px");
    ImGui::SliderFloat("Distant plane sigma", &state.sceneLighting.distantVoxelPlaneSigma, 0.25f, 6.0f, "%.2f px");
    ImGui::SliderFloat("Distant detail threshold", &state.sceneLighting.distantVoxelVarianceThreshold, 0.001f, 0.25f, "%.3f", ImGuiSliderFlags_Logarithmic);
    ImGui::EndDisabled();
    ImGui::TextDisabled("Depth-plane aware; leaves geometry normals, identities, and silhouettes unchanged");
    ImGui::SeparatorText("Ambient occlusion");
    ImGui::Checkbox("GTAO", &state.sceneLighting.gtaoEnabled);
    ImGui::SameLine();
    ImGui::TextDisabled("Contact shadows the probe grid cannot resolve");
    ImGui::BeginDisabled(!state.sceneLighting.gtaoEnabled);
    ImGui::DragFloat("AO radius", &state.sceneLighting.gtaoRadius, 0.01f, 0.01f, 64.0f, "%.2f world units");
    ImGui::SliderFloat("AO intensity", &state.sceneLighting.gtaoIntensity, 0.1f, 4.0f, "%.2f");
    ImGui::SliderFloat("AO thickness", &state.sceneLighting.gtaoThickness, 0.0f, 0.95f, "%.2f");
    {
      int slices = static_cast<int>(state.sceneLighting.gtaoSlices);
      if (ImGui::SliderInt("AO slices", &slices, 1, 8))
        state.sceneLighting.gtaoSlices = static_cast<uint32_t>(slices);
      int steps = static_cast<int>(state.sceneLighting.gtaoSteps);
      if (ImGui::SliderInt("AO steps", &steps, 1, 16))
        state.sceneLighting.gtaoSteps = static_cast<uint32_t>(steps);
    }
