    float terrainShadowBiasOverride = -1.0f;
    float terrainShadowStrengthOverride = -1.0f;
    int volumetricFogOverride = -1;
    float volumetricFogDensityOverride = -1.0f;
    float volumetricFogHeightOverride = -1.0f;
