    uint32_t windowWidth = 1920u;
    uint32_t windowHeight = 1080u;
    bool loadAllPages = false;
    bool testVSVORoundTrip = false;
    bool testVSVOSelective = false;
    bool depthOnly = false;
    bool lodEnabled = true;
    bool lightingEnabled = true;
    bool brickMeasureArea = false;
    bool brickRasterDiagnostics = false;
    // Columns per terrain mesh-proxy quad, or zero for the incumbent brick
    // overdraw measurement. See docs/sparse-voxel-terrain-mesh-proxy-plan.md.
    uint32_t terrainMeshProbeStride = 0u;
    bool terrainMeshVisibility = false;
    uint32_t terrainMeshCull = 0u;
    float terrainMeshLift = 0.0f;
    bool terrainMeshOnly = false;
    std::string frameDumpPath;
    bool ddgiEnabled = false;
    uint32_t ddgiRaysPerProbe = 32u;
    float ddgiSpacing = 4.0f;
    float ddgiUpdateFraction = 0.125f;
    bool ddgiPrimary = false;
    // On by default: without it the cache is 13x darker than the screen-probe
    // field it replaces, because that field carries the direct sun. The flag
    // exists to A/B the dithered-shadow artifact, which per-probe sun
    // visibility is the likely source of.
    bool ddgiSunInCache = true;
    uint32_t terrainMeshDilate = 1u;
    uint32_t terrainShellDepth = 0xffffffffu;
    float brickOcclusionDilationVoxels = 1.0f;
    float brickExactMicroDistanceCutoffMetres = 0.0f;
    // Exact microgeometry retired everywhere: 6.9 ms of a 17.5 ms raster+cull
    // block, for sub-voxel detail better spent on smaller voxels.
    // --brick-exact-micro-all restores it.
    float brickExactMicroMaxVoxel = 0.01f;
    bool brickMicroPrepareDiagnostic = false;
    // Distinguishes an explicit --brick-micro-prepare-diagnostic from the one
    // the R0 umbrella implies. The umbrella instruments the incumbent draw too,
    // so it must stay usable without the R2 split; only the explicit form is an
    // error against a graph that has no MicroPrepare passes.
    bool brickMicroPrepareDiagnosticRequested = false;
    // R2's compact/residual split is retained as an opt-in experiment, not as
    // the default raster. It is byte-identical to the incumbent full-brick draw
    // but its complete Phase0 chain remains slower on the canonical terrain
    // capture. See docs/sparse-voxel-raster-ddgi-implementation-plan.md, R2.
    bool brickMicroRasterEnabled = false;
    bool brickMicroMergedDraw = false;
    // Measured on the default terrain package at 1920x1080: raster+cull
    // 19.80 -> 14.57 ms, about half of everything exact microgeometry costs,
    // for microvoxels that project below two pixels. 1.0 restores the previous
    // behaviour bit-exactly.
    float microHandoffScale = 2.0f;
    bool brickTileBinDiagnostic = false;
    bool brickTileParity = false;
    bool brickTileMerge = false;
    bool brickTileMergeOverridden = false;
    float brickTileRoutePixels = 0.0f;
    bool brickTileRouteProvided = false;
    std::string profileDuplicateGroup;
    uint32_t brickMicroRecordCapacity = 0u;
    bool blasFrustumEnabled = true;
    // Nanite-style two-pass occlusion for the virtual-geometry route. Phase
    // one redraws last frame's drawn cluster set with the current camera into
    // the real target, the pyramid is built from that, and phase two draws what
    // survives it and was not already drawn. The alternative is the older
    // depth-only prepass, which rasterizes every cluster twice and runs at half
    // resolution to make that affordable.
    bool virtualGeometryTwoPhaseOcclusion = true;
    // Small triangles use the in-graph compute visibility path. On Apple,
    // native atomic64 is ordered with Vulkan through GPU timeline events.
    bool virtualGeometrySoftwareRaster = true;
    // Dormant native Metal atomic64 rasterizer (--vg-metal-raster).
    bool virtualGeometryMetalRaster = false;
    bool virtualGeometryUnifiedVisibility = true;
    bool occlusionEnabled = true;
    bool blasOcclusionEnabled = false;
    bool testOcclusionDisocclusion = false;
    bool testToggleOcclusion = false;
    uint32_t testTerrainFreezeFrame = std::numeric_limits<uint32_t>::max();
    uint32_t testDisableCullingFrame = std::numeric_limits<uint32_t>::max();
    bool testToggleTsr = false;
    // Disables TAA *and* TSR, which is a different code path from disabling TSR
    // alone: without TAA the whole temporal chain is never built, and that is
    // the configuration the right-hand-side lighting band was reported in.
    bool testToggleTaa = false;
    // Start with TAA and TSR off, rather than toggling them at frame 6. The
    // difference matters: toggling rebuilds the render graph, and starting
    // without one separates "this configuration is broken" from "the rebuild
    // into this configuration is broken".
    bool startWithoutTaa = false;
#if defined(__APPLE__)
    // MetalFX upscaling owns the default temporal path on macOS. Native frame
    // generation is opt-in: Metal instrumentation shows its drawable pacing
    // can hold the real source loop near 30 Hz even when rendering is faster.
    bool frameGeneration = true;
    bool metalFxUpscaler = true;
    bool metalFxFrameGeneration = true;
#else
    bool frameGeneration = false;
    bool metalFxUpscaler = false;
    bool metalFxFrameGeneration = false;
#endif
    // Eye height for --test-camera-interior, as a fraction of scene height.
    float testInteriorEyeHeight = -1.0f;
    // G-buffer debug view, matching SparseVoxelDebugMode. Negative leaves the
    // default. Exposed so the views - the overdraw one in particular - can be
    // exercised headlessly rather than only through ImGui.
    int debugModeOverride = -1;
    bool testCameraYaw = false;
    bool testCameraWalk = false;
    bool testCameraGroundForward = false;
    bool testCameraPreservePitch = false;
    // Ground-forward travel that turns around at the run's midpoint, so the
    // camera returns over ground it has already left (phase 8d: a retired
    // chunk coming back is a revive from the scratch file, not a mesh).
    bool testCameraOutAndBack = false;
    // Metres the ground-forward camera travels over the whole run. Zero keeps
    // the legacy page-derived cap, which is 4.5 m at the default 12.8 m page
    // and therefore never leaves the starting page - it cannot observe a page
    // handover or a spatial-LOD change, which is what a walking player does.
    double testCameraTravelMetres = 0.0;
    bool testCameraTravelProvided = false;
    uint32_t testCameraTravelStartFrame = 0u;
    uint32_t testCameraTravelFrames = 0u;
    // Degrees of yaw per frame applied on top of the ground-forward camera.
    // Rotation and streaming are separately covered by existing harnesses and
    // never together: --test-camera-walk oscillates inside terrain that is
    // already resident, and --test-camera-ground-forward holds its orientation.
    // The reported artifact needs both at once.
    double testCameraYawRateDegrees = 0.0;
    // Zero rotates for the whole run. A finite value rotates for exactly this
    // many frames and then holds the camera bit-stable so temporal lighting
    // convergence and post-rotation terrain coverage can be asserted.
    uint32_t testCameraYawFrames = 0u;
    // Delay deterministic yaw so a captured view can first build a stable
    // lighting history, then test that ordinary camera rotation reprojects it
    // instead of clearing it.
    uint32_t testCameraYawStartFrame = 0u;
    bool testTerrainStreaming = false;
    bool terrainV2Phase0 = false;
    std::filesystem::path terrainV2Phase0ReportPath;
    bool testTerrainOwnership = false;
    bool testTerrainLongRange = false;
    bool testWorldTerrainRaster = false;
    bool testWorldTerrainSlope = false;
    bool testWorldTerrain10cm = false;
    bool testTerrainGBuffer = false;
    bool testPlanetOverview = false;
    bool qualifyPlanetCbt = false;
    bool forceStaticPlanetOverview = false;
    bool forceAdaptivePlanetOverview = false;
    bool testCameraInterior = false;
    bool metalFxDenoiser = true;
    bool testCameraRoofDown = false;
    // Dolly the roof-down camera toward the floor and back, repeatedly.
    //
    // Every static test camera holds one distance, so none of them crosses an
    // LOD threshold - and the reported artifact only appears while crossing
    // one. This sweeps the whole distance band from "model fills a quarter of
    // the screen" to "model fills it", which is the motion the report
    // describes.
    bool testCameraDolly = false;
    bool testFrameSignatures = false;
    bool testRayHistory = false;
    // Headless terrain fixtures need to render feedback/publication frames
    // before their diagnostic readbacks describe a stable cut. Keep the
    // signature passes available from graph creation, but do not collect or
    // log their results until this absolute renderer frame.
    uint32_t testCaptureStartFrame = 0u;
    bool testStaticScene = false;
    // Deterministic exterior-shell fixture whose source materials all map to
    // one exact heightfield descriptor. This makes R1 exercise both compact
    // records and residual occupancy without an external terrain package.
    bool testMicroRaster = false;
    // Deterministic four-emitter fixture for checking that probe light
    // selection converges instead of leaving temporally dancing splats.
    bool testMultipleLights = false;
    bool testOccupancyShadow = false;
    bool testOccupancyHitCell = false;
    // --frames otherwise implies the output-signature readback, which adds a
    // full-screen GBufferSignature dispatch plus a whole-target copy. That is
    // ~7ms of GPU work per frame that no interactive run ever performs, so any
    // bounded timing run silently measures a configuration the app never ships.
    bool skipOutputSignature = false;
    // Emit one BLAS and instance per OBJ shape. A single whole-file model has a
    // root cube spanning the scene, so TLAS instance culling can never reject
    // anything; splitting gives it real granularity.
    bool splitOBJShapes = false;
    bool splitOBJMaterials = false;
    bool showPassTimeline = false;
    // Give every pass its own named Metal command buffer so an Instruments
    // Metal System Trace can attribute encoder time to it. Costs extra
    // submissions, so it measures proportions, not a shippable frame time.
    bool profilePasses = false;
    bool svgfEnabled = true;
    uint32_t svgfAtrousIterations = 5u;
    bool svgfAtrousIterationsProvided = false;
    bool spatialRestirEnabled = false;
    bool hardwareRestirEnabled = true;
    float hardwareSceneErrorPixels = 4.0f;
    bool screenTraceEnabled = true;
    bool collectScreenTraceStatistics = false;
    // Zero keeps the automatic near-field span derived from the fine cell.
    float screenTraceDistance = 0.0f;
    float screenTraceThicknessSteps = 0.0f;
    float screenTraceCellSpan = 0.0f;
    float screenTraceMaximumThicknessCells = 0.0f;
    float screenTraceStartPixels = 0.0f;
    bool screenTraceResumesWorldTrace = false;
    // FIFO quantises presentation to whole refresh intervals, so a frame that
    // misses 16.7ms drops straight to 30fps and one that misses 33.3ms to 20.
    // That reads as a much worse stutter than the underlying variation, which
    // is misleading while the frame cost is being tuned. --vsync restores it.
    bool vsyncEnabled = false;
    bool separateGpuQueues = false;
    // Zero means the command line did not override the quality defaults.
    uint32_t rayResolutionDivisor = 0u;
    uint32_t raysPerPixel = 0u;
    uint32_t restirCandidatesPerPixel = 0u;
    float restirMaximumWeight = 0.0f;
    bool gtaoDisabled = false;
    int lightingScaleOverride = -1;
    int lightingAccumulationFrames = -1;
    std::string lightFieldQuality;
    float analyticLightingDistanceOverride = -1.0f;
    float maximumRayDistanceOverride = -1.0f;
    int gtaoSlicesOverride = -1;
    int gtaoStepsOverride = -1;
    // Negative means "leave the demand-driven defaults alone".  Zero is a
    // meaningful value: settled receivers sleep until history invalidation.
    float rayRefreshInterval = -1.0f;
    int minimumConvergedSamples = -1;
    float convergenceRelativeError = -1.0f;
    int stableObservationCount = -1;
    int regionStabilityTileSize = -1;
    int regionWakeFrames = -1;
    // Negative keeps the pass default. See the pass setting for what it gates.
    float lightFieldHistoryDepth = -1.0f;
    float lightFieldHistoryNormal = -2.0f;
    float regionSoftVisibilityThreshold = -1.0f;
    int regionSoftVisibilityStreak = -1;
    int regionSoftPrefillStride = -1;
    std::string diMode;
    int probeTileSize = -1;
    float probeDepthThreshold = -1.0f;
    int probeAdaptivePercent = -1;
    int probeConvergedInterval = -1;
    int probeAsleepInterval = -1;
    int probeAwakeRays = -1;
    int probeAwakeInterval = -1;
    int probeMinimumUpdates = -1;
    float probeMaximumError = -1.0f;
    int probeConvergedRuns = -1;
    int probeAsleepRuns = -1;
    int probeWakeFrames = -1;
    float probeDensityHalfDistance = -1.0f;
    float probeDensityQuarterDistance = -1.0f;
    float probeLocalLightCullStartDistance = -1.0f;
    float probeSkyOnlyDistance = -1.0f;
    int probeMaximumDensityStride = -1;
    float tree64TraceExtentScale = -1.0f;
    float renderScale = -1.0f;
    bool renderScaleProvided = false;
