    bool tonemapAccumulation = false;
    bool accumulationWeighting = true;
    bool robustSharpen = true;
    bool reconstructedDepth = false;
    bool exposureEnabled = true;
    float rectificationBoxScale = -1.0f;
    float shadingChangeStrength = -1.0f;
    float shadingChangeStops = -1.0f;
    float depthSeparationScale = -1.0f;
    float sharpenStrength = -1.0f;
