    float rayTileBudgetBoost = -1.0f;
    int rayTileBudgetHeartbeat = -1;
    bool visibleVoxelTracing = false;
    bool visibleVoxelTracingDisabled = false;
    uint32_t visibleVoxelTileWidth = 2u;
    bool visibleVoxelFiveRay = false;
    float traceBiasCells = 0.0f;
