          const int lod = std::stoi(token, &consumed);
          if (consumed != token.size())
            throw std::runtime_error("--terrain-requested-lods contains an invalid level");
          if (lod < 0 || lod >= static_cast<int>(svr::kPlanetVoxelMaximumLODLevels))
            throw std::runtime_error("--terrain-requested-lods entries must be in 0..7");
          terrainRequestedLODMask |= uint32_t{1u} << lod;
          if (comma == std::string::npos)
            break;
          begin = comma + 1u;
