      const size_t programmedMaterials = static_cast<size_t>(std::count_if(
          programs.begin(),
          programs.end(),
          [](const voxelMaterial::VoxelShadingProgramGPU &program)
          {
            return program.instructionCount != 0u;
          }));
      const auto &microDescriptors = state.terrainMaterial.materialManager.descriptors();
      const size_t carvedMaterials = static_cast<size_t>(std::count_if(
          microDescriptors.begin(),
          microDescriptors.end(),
          [](const svr::SparseVoxelMicroMaterialGPU &descriptor)
          {
            return ((descriptor.geometry >> 4u) & 0xffu) != 0u;
          }));
      const size_t slopeMaterials = static_cast<size_t>(std::count_if(
          microDescriptors.begin(),
          microDescriptors.end(),
          [](const svr::SparseVoxelMicroMaterialGPU &descriptor)
          {
            const uint32_t profile = (descriptor.geometry >> 18u) & 0x07u;
            return ((descriptor.geometry >> 4u) & 0xffu) != 0u && profile == static_cast<uint32_t>(svr::SparseVoxelMicroGeometryProfile::Staircase);
          }));
